import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Roadmap","description":"Planned features, future enhancements, and the long-term vision for AzureScout.","frontmatter":{"description":"Planned features, future enhancements, and the long-term vision for AzureScout."},"headers":[],"relativePath":"project/roadmap.md","filePath":"project/roadmap.md"}'),n={name:"project/roadmap.md"};function s(i,e,d,c,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p><em>See everything. Own your cloud.</em></p><p>This page outlines what&#39;s planned, what&#39;s in progress, and what&#39;s been delivered. Community contributions are welcome — see <a href="./contributing.html">Contributing</a> to get involved.</p><blockquote><p>The consolidated architecture, work-item index, audit findings, and delivery plan live in the <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/pmo/plans/master-plan.md" target="_blank" rel="noreferrer">Master Design &amp; Plan</a>. This roadmap is the public-facing summary of it.</p></blockquote><h2 id="v3-0-0-engine-rebuild-status" tabindex="-1">v3.0.0 engine rebuild status <a class="header-anchor" href="#v3-0-0-engine-rebuild-status" aria-label="Permalink to &quot;v3.0.0 engine rebuild status&quot;">​</a></h2><p><strong>Epic AB#5638 is ready for v3.0.0 release validation.</strong> The declarative collector catalog has replaced the retired source-script tree. Publication follows the final package and full-suite gates.</p><p>Measured on <code>main</code> as of 26 July 2026:</p><table tabindex="0"><thead><tr><th>Acceptance criterion</th><th>Target</th><th>Actual</th></tr></thead><tbody><tr><td>Retired collector source tree</td><td>absent</td><td><strong>removed</strong></td></tr><tr><td>Declarative collector catalog</td><td>every collector</td><td><strong>236</strong> (<code>manifests/collectors/*.psd1</code>) — 174 at v3.0.9, +62 in v3.1.0</td></tr><tr><td>Strict declarative processing</td><td>all collectors</td><td><strong>236/236 verified</strong></td></tr><tr><td>Golden report contract</td><td>rows + two worksheet modes</td><td><strong>236 rows / 472 worksheet cases verified</strong></td></tr><tr><td>Inventory and assessment share one reporting layer</td><td>cut over</td><td><strong>declarative reporting path</strong></td></tr><tr><td>Three consecutive runs on an unchanged estate are identical</td><td>yes</td><td><strong>yes</strong> (v2.6.0)</td></tr></tbody></table><p>Reporting reads each definition&#39;s <code>Export</code> section through the same manifest catalog as processing; there is no collector-script reporting branch.</p><p>You can check every number yourself — <code>scripts/Test-StrictModeGuard.ps1</code> prints the weakening-site count, and the rest are file counts.</p><h3 id="v3-0-0-completion-criteria" tabindex="-1">v3.0.0 completion criteria <a class="header-anchor" href="#v3-0-0-completion-criteria" aria-label="Permalink to &quot;v3.0.0 completion criteria&quot;">​</a></h3><p>All collector definitions, source retirement, strict runtime contracts, and reporting contracts are complete. The remaining release steps are package validation, broad test-suite completion, tag, and publication. Historical v2 entries below are retained as release history rather than current status.</p><h2 id="current-release-—-v3-12-7-—-the-report-always-comes-home" tabindex="-1">Current Release — v3.12.7 — the report always comes home <a class="header-anchor" href="#current-release-—-v3-12-7-—-the-report-always-comes-home" aria-label="Permalink to &quot;Current Release — v3.12.7 — the report always comes home&quot;">​</a></h2><p>Released 14 August 2026. A combined run whose scored assessment stops safely because required evidence is unavailable now reuses the completed inventory to render React and JsonEvidence without another Azure call, writing the deliverable into the predictable <code>assessment-report</code> folder. React indexing tolerates open-ended Azure values, including Boolean <code>name</code> fields. The built-in progress renderer now shows a high-contrast bordered multi-phase ledger whose elapsed clock continues during blocking operations. See CHANGELOG.md and AB#405.</p><h2 id="previous-release-—-v3-12-6-—-the-progress-display-ships-with-scout" tabindex="-1">Previous Release — v3.12.6 — the progress display ships with Scout <a class="header-anchor" href="#previous-release-—-v3-12-6-—-the-progress-display-ships-with-scout" aria-label="Permalink to &quot;Previous Release — v3.12.6 — the progress display ships with Scout&quot;">​</a></h2><p>Released 13 August 2026. AzureScout ships a self-contained native live renderer with no third-party progress dependency. Its spinner, progress bar, phase text, and elapsed clock start during permission preflight and cover extraction, diagrams and supplemental processing, assessment and inventory rendering, and deterministic collector processing. CI, redirected, and <code>-NoProgress</code> runs keep their safe fallbacks. See CHANGELOG.md and AB#405.</p><h2 id="previous-release-—-v3-12-5-—-the-compass-keeps-moving" tabindex="-1">Previous Release — v3.12.5 — the compass keeps moving <a class="header-anchor" href="#previous-release-—-v3-12-5-—-the-compass-keeps-moving" aria-label="Permalink to &quot;Previous Release — v3.12.5 — the compass keeps moving&quot;">​</a></h2><p>Released 13 August 2026. Interactive inventory extraction now uses a real auto-refreshing optional Spectre progress host, keeping its spinner and elapsed clock moving during blocking Azure calls. High-contrast phase labels use no colored background, <code>-NoProgress</code> gives operators an explicit quiet mode, native/CI fallbacks remain intact, and renderer failures cannot replay collector work. See CHANGELOG.md and AB#405.</p><h2 id="previous-release-—-v3-12-4-—-close-the-reconciliation-gaps" tabindex="-1">Previous Release — v3.12.4 — close the reconciliation gaps <a class="header-anchor" href="#previous-release-—-v3-12-4-—-close-the-reconciliation-gaps" aria-label="Permalink to &quot;Previous Release — v3.12.4 — close the reconciliation gaps&quot;">​</a></h2><p>Released 13 August 2026. Seven dedicated collectors now cover every live resource type found only in raw inventory during the independent tenant reconciliation, taking the catalog to 285. ARM child collection follows continuation links. Key Vault secret/key inventory uses paged metadata-only LIST operations, never reads values or private key material, and reports missing access explicitly rather than returning an incomplete first page. Key Vault assessment mapping and network diagram job tracking are also corrected. See CHANGELOG.md and AB#7358.</p><h2 id="previous-release-—-v3-12-3-—-every-collector-tells-the-truth" tabindex="-1">Previous Release — v3.12.3 — every collector tells the truth <a class="header-anchor" href="#previous-release-—-v3-12-3-—-every-collector-tells-the-truth" aria-label="Permalink to &quot;Previous Release — v3.12.3 — every collector tells the truth&quot;">​</a></h2><p>Released 11 August 2026. ARM child discovery now runs on supported Az.Accounts versions and propagates exact per-dataset availability. Risky Users, Verified ID, management-group, Defender, and Azure DevOps checks report the real permission, licence, provider, or HTTP boundary instead of silently returning empty data. Operational extraction shows bounded progress and durable heartbeats, and every run log closes with a terminal status. A live read-only HCS acceptance pass independently reconciled all 278 collectors while preserving raw inventory and every cache/health artifact. See CHANGELOG.md and AB#7279.</p><h2 id="previous-release-—-v3-12-2-—-honest-collection-retained-evidence" tabindex="-1">Previous Release — v3.12.2 — honest collection, retained evidence <a class="header-anchor" href="#previous-release-—-v3-12-2-—-honest-collection-retained-evidence" aria-label="Permalink to &quot;Previous Release — v3.12.2 — honest collection, retained evidence&quot;">​</a></h2><p>Released 11 August 2026. Guided runs authenticate and audit once, with management-group and Graph readiness based on data the selected identity can actually collect. Scout classifies known Graph availability boundaries before requests, removes the held Lighthouse query, retries oversized Security Center results with smaller pages, and treats normal 404/provider absence as expected. Collection health distinguishes unavailable data from a genuinely empty estate, and every raw/cache artifact remains available until explicit operator cleanup. See CHANGELOG.md and AB#7279.</p><h2 id="previous-release-—-v3-12-1-—-one-sign-in-one-tenant" tabindex="-1">Previous Release — v3.12.1 — one sign-in, one tenant <a class="header-anchor" href="#previous-release-—-v3-12-1-—-one-sign-in-one-tenant" aria-label="Permalink to &quot;Previous Release — v3.12.1 — one sign-in, one tenant&quot;">​</a></h2><p>Released 11 August 2026. Microsoft Graph now uses the same selected Azure PowerShell account and tenant as ARM collection and never consults an unrelated Azure CLI session. A common Entra authentication failure is attempted and reported once instead of repeated for every dataset. See CHANGELOG.md and AB#7279.</p><h2 id="previous-release-—-v3-12-0-—-less-waiting-same-evidence" tabindex="-1">Previous Release — v3.12.0 — less waiting, same evidence <a class="header-anchor" href="#previous-release-—-v3-12-0-—-less-waiting-same-evidence" aria-label="Permalink to &quot;Previous Release — v3.12.0 — less waiting, same evidence&quot;">​</a></h2><p>Released 10 August 2026. Category-filtered inventory now avoids unrelated remote work through a manifest-derived dependency plan and server-side Resource Graph filters. Combined runs reuse the completed inventory security/policy sweep; Recovery Services and storage enrichment cache calls at subscription or vault scope; and the ARM REST sweep uses pagination and transient-only retry instead of fixed success-path sleeps. Full, unknown, and assessment-backed paths retain complete evidence coverage. See CHANGELOG.md and AB#7279.</p><h2 id="previous-release-—-v3-11-0-—-one-output-contract-logs-that-explain-the-run" tabindex="-1">Previous Release — v3.11.0 — one output contract, logs that explain the run <a class="header-anchor" href="#previous-release-—-v3-11-0-—-one-output-contract-logs-that-explain-the-run" aria-label="Permalink to &quot;Previous Release — v3.11.0 — one output contract, logs that explain the run&quot;">​</a></h2><p>Released 10 August 2026. Inventory, assessment, combined, wizard, and automation paths now share one live output contract: React, Json, and JsonEvidence. Inventory-only React and evidence reuse the completed collection offline, while Json preserves the inventory contract. Detailed DEBUG/VERBOSE phase, row-count, timing, rule, and renderer diagnostics are written to the run log by default without increasing console noise. See CHANGELOG.md and AB#7279.</p><h2 id="previous-release-—-v3-10-2-—-tenant-means-tenant" tabindex="-1">Previous Release — v3.10.2 — tenant means tenant <a class="header-anchor" href="#previous-release-—-v3-10-2-—-tenant-means-tenant" aria-label="Permalink to &quot;Previous Release — v3.10.2 — tenant means tenant&quot;">​</a></h2><p>Released 10 August 2026. Restores the guided wizard&#39;s tenant-first contract: the prompt shows the signed-in user and tenant display name, Y keeps that tenant, and N forces a fresh login then lists accessible tenants rather than subscriptions. The default tenant-wide ARM inventory no longer requests a Microsoft Graph token; Entra collection is an explicit opt-in. See CHANGELOG.md and AB#7278.</p><h2 id="previous-release-—-v3-10-1-—-combined-means-combined" tabindex="-1">Previous Release — v3.10.1 — combined means combined <a class="header-anchor" href="#previous-release-—-v3-10-1-—-combined-means-combined" aria-label="Permalink to &quot;Previous Release — v3.10.1 — combined means combined&quot;">​</a></h2><p>Released 10 August 2026. Fixes the v3.10.0 startup rejection for a combined inventory + assessment run with React/JsonEvidence, then closes the related runtime and correctness gaps found by the full audit: tenant-scoped Graph calls, deterministic context and job ownership, honest governance/compliance availability, canonical report scoring/evidence, complete rule collection dependencies, strict dependency/import behavior, and fail-closed zero-skip release gates. See CHANGELOG.md and AB#7278.</p><h2 id="previous-release-—-v3-10-0-—-the-last-three-closed-for-real" tabindex="-1">Previous Release — v3.10.0 — the last three, closed for real <a class="header-anchor" href="#previous-release-—-v3-10-0-—-the-last-three-closed-for-real" aria-label="Permalink to &quot;Previous Release — v3.10.0 — the last three, closed for real&quot;">​</a></h2><p>Released 9 August 2026. Executive/Consultant/Data view modes now materially differ on every report section, not just 2 of 6; the Azure Landing Zone assessment renders BECU-style per-domain chapters (scorecard, current-state prose, grouped findings, figure) per CAF design area instead of one flat list, with the ALZ benchmark broken into its own section; fixed a self-contradicting scorecard caused by two design areas sharing the literal name &quot;Security&quot;, and the underlying evidence-identity defect where a single-match finding&#39;s evidence could resolve to .NET type metadata instead of a resource name; PSScriptAnalyzer is at zero Error/Warning violations repo-wide, down from 1,465. See CHANGELOG.md for the full per-story breakdown.</p><h2 id="previous-release-—-v3-9-0-—-the-backlog-sweep" tabindex="-1">Previous Release — v3.9.0 — the backlog sweep <a class="header-anchor" href="#previous-release-—-v3-9-0-—-the-backlog-sweep" aria-label="Permalink to &quot;Previous Release — v3.9.0 — the backlog sweep&quot;">​</a></h2><p>Released 9 August 2026. Closes out the open coverage-gap backlog across ten service categories (Analytics, IoT, DevOps, Management and governance, AI and machine learning, Storage, Compute, Security, Databases, Networking) with real new collectors wired end to end into the assessment collect, not only the inventory Excel export; adds cost projections and Azure Local licence/Hybrid Benefit collection; surfaces previously-dropped collected categories (Defender alert/assessment/secure-score detail, Azure Local child resources) in the React report; and makes the wizard&#39;s category and format menus honest about what they actually collect, with coverage figures generated from the collector manifests rather than hand-typed. See CHANGELOG.md for the full per-story breakdown.</p><h2 id="previous-release-—-v3-6-0-—-the-collector-payload-wiring-audit-closed-out" tabindex="-1">Previous Release — v3.6.0 — The collector-payload wiring audit, closed out <a class="header-anchor" href="#previous-release-—-v3-6-0-—-the-collector-payload-wiring-audit-closed-out" aria-label="Permalink to &quot;Previous Release — v3.6.0 — The collector-payload wiring audit, closed out&quot;">​</a></h2><p>Released 8 August 2026. Nearly 100 collector manifests existed, were fully tested, and produced Excel-only rows — but never reached the assessment collect (<code>collect.json</code>) the React report actually renders from. This release closes that gap: 95 collectors wired across Networking, Hybrid, Monitor, Defender, Databases, DevOps, Management, Security, Storage, and Update Manager categories (coverage moves from 77 to 172 of 245 tracked manifests), plus 3 genuinely new collectors authored from scratch for services that had none — Microsoft Entra Verified ID and Microsoft Entra External ID (the governance/landing-zone-relevant one), both Graph-backed rather than ARM/ARG. Along the way, a real defect in the test suite&#39;s own infrastructure was found and fixed: a shared mock-cleanup idiom silently no-opped, letting mock state leak across test files — corrected everywhere it appeared.</p><h2 id="previous-release-—-v3-5-1-—-three-things-v3-5-0-said-were-fine" tabindex="-1">Previous Release — v3.5.1 — Three things v3.5.0 said were fine <a class="header-anchor" href="#previous-release-—-v3-5-1-—-three-things-v3-5-0-said-were-fine" aria-label="Permalink to &quot;Previous Release — v3.5.1 — Three things v3.5.0 said were fine&quot;">​</a></h2><p>Released 4 August 2026. Three things v3.5.0 said were fine — each found by <em>using</em> the product, not by reading test results. The wizard offered every format except the one it renders: picking inventory + assessment (the commonest path) fell through to the inventory-only list, which has no React, while the list it skipped still offered six held renderers with Html as the default; a menu-honesty test now fails if the wizard ever offers a format the product declines to produce. One tenant in eight could not render: dotted member enumeration over an <em>empty</em> collection resolves against the array object, so a tenant with management groups but no policy assignments threw and produced nothing — all eight corpus tenants now render. The diagram-overlap gate was green because it inspected nothing — the fixture wrote flat keys while the payload uses dotted paths, so every diagram hit its empty guard; the gate now reads real topology and was proved to fail on a manufactured overlap.</p><h2 id="previous-release-—-v3-5-0-—-the-report-is-a-product-not-a-page" tabindex="-1">Previous Release — v3.5.0 — The report is a product, not a page <a class="header-anchor" href="#previous-release-—-v3-5-0-—-the-report-is-a-product-not-a-page" aria-label="Permalink to &quot;Previous Release — v3.5.0 — The report is a product, not a page&quot;">​</a></h2><p>Released 4 August 2026. The report is a product, not a page. The owner-approved v6 design ships: the React report becomes a multi-page application — Overview, Inventory &amp; audit, Assessments, Diagrams, Data &amp; drift, Remediation plan — rendered from the run&#39;s own data. Inventory becomes a blade view on the documented 18-category taxonomy with every collector listed including zeros, filterable/sortable item tables, tenant structure, audit callouts and a full cost-optimization blade. Each assessment carries the complete conformance register: every check, a gap block for every fail (resource-grain evidence, why it matters, numbered fix, per-check Learn link), the manual review agenda, and a What&#39;s-next section. A Diagrams page adds MG hierarchy, VNet/subnet IP utilization, estate and gaps figures with full-screen zoom. Executive/Consultant/Data become a depth toggle; exports add Markdown and JSON. Conformance clause R-04 is enforced for real — the renderer no longer re-invokes the scoring engine. All other assessment formats remain on hold. See AB#6928, AB#6936, AB#6937, AB#6938, AB#7035.</p><h2 id="previous-release-—-v3-3-4-—-one-report-and-it-is-the-deliverable" tabindex="-1">Previous Release — v3.3.4 — One report, and it is the deliverable <a class="header-anchor" href="#previous-release-—-v3-3-4-—-one-report-and-it-is-the-deliverable" aria-label="Permalink to &quot;Previous Release — v3.3.4 — One report, and it is the deliverable&quot;">​</a></h2><p>Released 4 August 2026. A full multi-tenant render, read end to end rather than counted, found every one of the six rendered report formats weak in a different way — a dashboard that drew its headers and no data, a maturity report scoring 10/10 without saying what it measured, documents that never named which assessment they were, text drawn over text in the PDF, figures running off the slide, and a Word file that opened with a repair prompt. Six renderers maintained in parallel is why none of them reached deliverable quality.</p><p>The <strong>React single-page report</strong> is now the product&#39;s deliverable: one self-contained page hosting the inventory and every assessment behind an adaptive shell whose navigation is built from what actually ran. Each assessment answers what was run (including what was <em>not</em> assessed and why), what was found, and what to fix against CAF/WAF guidance — and every score carries its own arithmetic, so a number can be checked rather than trusted.</p><p>Every other rendered format is on hold and will be regenerated from that report rather than alongside it. <code>Json</code>/<code>JsonEvidence</code> are data, not documents, and are never held. A held format asked for by name warns, skips, and renders the React report anyway, so a run never returns an empty folder.</p><h2 id="previous-release-—-v3-3-3-—-the-corpus-told-the-truth" tabindex="-1">Previous Release — v3.3.3 — The corpus told the truth <a class="header-anchor" href="#previous-release-—-v3-3-3-—-the-corpus-told-the-truth" aria-label="Permalink to &quot;Previous Release — v3.3.3 — The corpus told the truth&quot;">​</a></h2><p>Released 3 August 2026. Five collection defects fixed, none of which a green unit suite could see: the v3.3.2 Recovery Services vault fix never reached the collect result; Export-Pptx&#39;s module-scope <code>Get-ScoutProp</code> shadowed the collect walker and nulled nested <code>properties.*</code> on every product run (the defect that corrupted the banked corpus); management groups are collected for the first time in the product&#39;s history (tenant-scoped Resource Graph, 92 groups across the eight reference tenants); <code>security.defenderPlans</code> is collected per subscription instead of shipping as a hardcoded empty array the CAF/WAF security rules queried in vain; and two runs in the same second no longer share one run folder. The corpus is now a committed harness — per-tenant integrity checks on collection, per-collector coverage verdicts offline: 36 collect keys proven working across 8 real tenants, 0 unexplained empties.</p><h2 id="v3-3-2-—-field-fixes-from-real-tenant-runs" tabindex="-1">v3.3.2 — Field fixes from real tenant runs <a class="header-anchor" href="#v3-3-2-—-field-fixes-from-real-tenant-runs" aria-label="Permalink to &quot;v3.3.2 — Field fixes from real tenant runs&quot;">​</a></h2><p>Released 3 August 2026. Every fix in this release came from running Scout against live estates. Advisor ingestion is contained per subscription instead of failing tenant-wide on one unregistered <code>Microsoft.Advisor</code> provider; Entra ID P2-gated Graph features report <code>NOT LICENSED</code> instead of a misleading <code>DENIED</code>; Recovery Services vaults are collected instead of hardcoded to an empty array; the <code>CAF: Azure Landing Zone</code> assessment scores its own 13 areas instead of sweeping in every workload rule set; <code>GovernanceReport</code> is reachable from <code>-OutputFormat All</code>; and evidence truncation is visible in every renderer. The v3.3 line (3.3.0 → 3.3.2) delivered the reporting rebuild of Epic AB#6450: conformance-gated Word/Excel/PowerPoint/PDF deliverables, managed-code figure rasterisation, and a Power BI PBIP project with a TMDL model and bound visuals.</p><h2 id="v3-2-0-—-deep-governance-and-compliance-analytics" tabindex="-1">v3.2.0 — Deep governance and compliance analytics <a class="header-anchor" href="#v3-2-0-—-deep-governance-and-compliance-analytics" aria-label="Permalink to &quot;v3.2.0 — Deep governance and compliance analytics&quot;">​</a></h2><p>Released 31 July 2026. Scout modelled fifteen of Microsoft&#39;s eighteen published service categories; it now models all eighteen. <code>Migration</code> went from zero collectors to all five of its services, and <code>General</code> and <code>DevOps</code> exist for the first time. 62 collectors were added, taking measured service coverage from <strong>41% to 66%</strong> of the 349 services the audit enumerates — recounted mechanically from the per-service table, not asserted.</p><p>Four things this release fixed that had shipped in every prior one: Logic Apps were excluded from the Resource Graph query outright; the golden collector suite failed on any day but the one it was recorded on; the wizard resolved its assessment manifest to a path outside the repository and so never listed more than one assessment; and <code>-Category DevOps</code>/<code>Migration</code> were documented aliases that parameter binding rejected.</p><p>New capability rather than new collectors: the rule engine can now express a condition spanning two collected datasets, declared as rule data, so &quot;which VMs have no backup&quot; is answerable — six such rules ship. Key Vault secret and key expiry, blob-container public access, file shares, lifecycle policies and Backup vault instances are collected for the first time, all on the control plane and all within Reader. The SMART migration-readiness assessment ships with its source framework enumerated and date-stamped first, including an explicit record of what could not be enumerated. See <strong>Epic AB#6741</strong>.</p><h2 id="caf-waf-assessment-programme" tabindex="-1">CAF/WAF assessment programme <a class="header-anchor" href="#caf-waf-assessment-programme" aria-label="Permalink to &quot;CAF/WAF assessment programme&quot;">​</a></h2><p><strong>Planned, from the Epic AB#6731 audit. Scout ships one real assessment today: <code>CAF: Azure Landing Zone</code>.</strong> Everything else in <code>manifests/assessments.psd1</code> is either a filtered slice of that same rule set (the 15 per-category entries, prefixed <code>Assess: </code> as of this release — see the <a href="./../design/assessment-registry.html">Assessment Registry</a>), a sub-bundle, or <code>Scout: Cost Optimization</code>. Microsoft&#39;s own <a href="https://learn.microsoft.com/assessments/browse/" target="_blank" rel="noreferrer">assessment catalogue</a> lists 56 published assessments; of those, an owner-decided set of <strong>14</strong> are Scout&#39;s build targets for the next several releases — chosen because Scout already collects data for most of them, or is uniquely positioned to score them (Azure Local, in particular — see below).</p><table tabindex="0"><thead><tr><th>#</th><th>Target</th><th>Scout&#39;s starting position</th></tr></thead><tbody><tr><td>1</td><td>Azure Well-Architected Review</td><td><code>waf.*</code> rule files exist, tagged by pillar — <strong>~15% solid coverage</strong> against the WAF checklist&#39;s ~26 machine-assessable items</td></tr><tr><td>2</td><td>Azure Landing Zone Review</td><td><code>CAF: Azure Landing Zone</code> already aims at this — <strong>~10%</strong> of CAF&#39;s ~365 verified design-area recommendations</td></tr><tr><td>3</td><td>Azure Local | Well-Architected Review</td><td><strong>Scout&#39;s strongest differentiator</strong> — 16 Hybrid collectors, no WAF-shaped rule output yet</td></tr><tr><td>4</td><td>WAF AI workload</td><td>AI is Scout&#39;s best-inventoried category; rules are thin (<code>caf.ai</code>, 5 rules)</td></tr><tr><td>5</td><td>WAF Azure Virtual Desktop workload</td><td>7 AVD collectors exist; no AVD-specific rule file</td></tr><tr><td>6</td><td>WAF Azure VMware Solution workload</td><td>AVS collected; no AVS rule file</td></tr><tr><td>7</td><td>AVS Landing Zone Review</td><td>Pairs with #6 — platform readiness rather than workload</td></tr><tr><td>8</td><td>Cloud Governance</td><td>Policy compliance state is already collected and scored by nothing</td></tr><tr><td>9</td><td>FinOps Review</td><td><code>waf.cost</code> (6 rules) + a misnamed <code>caf.billing.yaml</code> that actually holds cost-optimization rules</td></tr><tr><td>10</td><td>DevOps Capability Assessment</td><td>5 DevOps collectors exist via the Azure DevOps REST API</td></tr><tr><td>11</td><td>Microsoft Cloud Security Benchmark (MCSB)</td><td>Not on Microsoft&#39;s assessment catalogue — it&#39;s an Azure Policy initiative (223 policies, assigned by default in Defender for Cloud). The compliance state is already collected via three code paths and read by no rule — <strong>cheapest assessment on this list, no new Azure calls</strong></td></tr><tr><td>12</td><td>WAF Maturity Model</td><td>Same rules as #1, different output shape (&quot;level 2 of 5&quot; vs. a fail list)</td></tr><tr><td>13</td><td>Cloud Adoption Security Assessment (CASA)</td><td>Aligned to the CAF <strong>Secure</strong> methodology, which Scout does not model at all today</td></tr><tr><td>14</td><td>Strategic Migration Assessment (SMART)</td><td>Blocked until the Migration category has collectors — <strong>shipped in v3.1.0</strong>; <code>smart.migration.yaml</code> is scored against the enumerated source in <a href="./../frameworks/smart-question-set.html">SMART&#39;s framework page</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Only 2 of 14 are design-ready</p><p>Writing a rule file against a framework nobody enumerated is how <code>waf.storage.yaml</code> happened — a rule file that scores a WAF pillar (Storage) that doesn&#39;t exist; WAF has exactly five pillars. Only <strong>#1 Azure Well-Architected Review</strong> (the 5-pillar checklist) and <strong>#2 Azure Landing Zone Review</strong> (the 8 CAF design areas) have their source structure enumerated and coverage-measured today — both in the audit document, §8. <strong>#14 SMART</strong> now has its source enumerated too (linked above). The remaining eleven each need their own enumeration — a published Microsoft checklist or question set, read and tabulated — as a prerequisite task before any rule file is written against them, because Microsoft is actively rewriting several of these pages and a coverage number without a verification date and method will silently go stale.</p></div><p><strong>What blocks the most assessments is Scout&#39;s own defect, not new collectors.</strong> <code>-IncludeTenantWideResources</code> used to gate management groups, custom role definitions, policy definitions and policy set definitions behind a switch no production caller ever set — fixed in this release (see <a href="#current-release-v3-1-0-eighteen-category-service-coverage">v3.1.0</a> history below) — and that single fix unblocks #2, #7, #8 and #13. A second near-free win: role assignments, resource locks, policy assignments and budgets are already collected into memory and rendered by nothing, which is most of what blocks #8 Cloud Governance outright.</p><p><strong>Deliberately excluded:</strong> partner-enablement guides, skills assessments, and industry-vertical readiness guides from Microsoft&#39;s catalogue. Those are training material, not something a scanning tool can produce.</p><p>Full detail, the release-order dependency map, and the underlying evidence: <code>pmo/audits/AZURE-SCOUT-AUDIT.md</code> §8, §13 (decisions DQ1/DQ2/DQ10-DQ12), and §14.</p><h2 id="v3-0-9-—-live-run-hardening" tabindex="-1">v3.0.9 — Live-run hardening <a class="header-anchor" href="#v3-0-9-—-live-run-hardening" aria-label="Permalink to &quot;v3.0.9 — Live-run hardening&quot;">​</a></h2><p>Released 30 July 2026. A live run against a real 8-subscription tenant surfaced two fatal crashes (JSON report export, SupportTickets collector) plus six further defects: no retry/backoff in the operational-enrichment ARM helper, a permanently-broken Arc CPU metrics call, an expected-but-noisy ReplicationEligibility 404, a wizard Scope/Entra silent-default gap that caused zero Entra ID data to be collected despite full permissions, a missing Cost Data module pre-flight check, and an unclear DefenderAlerts null-reference message. See <strong>Epic AB#6731</strong> for the full defect list and fixes.</p><h2 id="v3-0-8-—-az-breaking-change-warning-suppression" tabindex="-1">v3.0.8 — Az breaking-change warning suppression <a class="header-anchor" href="#v3-0-8-—-az-breaking-change-warning-suppression" aria-label="Permalink to &quot;v3.0.8 — Az breaking-change warning suppression&quot;">​</a></h2><p>Released 29 July 2026. Suppresses Az module breaking-change warnings in non-debug output.</p><h2 id="v3-0-7-—-strictmode-common-parameter-fix" tabindex="-1">v3.0.7 — StrictMode common-parameter fix <a class="header-anchor" href="#v3-0-7-—-strictmode-common-parameter-fix" aria-label="Permalink to &quot;v3.0.7 — StrictMode common-parameter fix&quot;">​</a></h2><p>Released 29 July 2026. Avoids a StrictMode <code>VariableIsUndefined</code> error when common parameters such as <code>-Debug</code> are supplied to <code>Invoke-AzureScout</code>.</p><h2 id="v3-0-6-—-excel-and-arc-resilience" tabindex="-1">v3.0.6 — Excel and ARC resilience <a class="header-anchor" href="#v3-0-6-—-excel-and-arc-resilience" aria-label="Permalink to &quot;v3.0.6 — Excel and ARC resilience&quot;">​</a></h2><p>Released 28 July 2026. Resilience and logging improvements for the Excel report build and ARC-enabled server collection.</p><h2 id="v3-0-5-—-vm-cost-row-regression-correction" tabindex="-1">v3.0.5 — VM cost-row regression correction <a class="header-anchor" href="#v3-0-5-—-vm-cost-row-regression-correction" aria-label="Permalink to &quot;v3.0.5 — VM cost-row regression correction&quot;">​</a></h2><p>Released 28 July 2026. This patch keeps production VM reporting running when Cost Management returns the amount and currency as a nested row. Clean Gallery v3.0.5 live verification completed on 29 July 2026 with <code>-Scope ArmOnly</code>: 174 declarative collectors run, 0 failures, and 1,121 Excel rows written.</p><h2 id="v3-0-4-—-vm-runtime-regression-correction" tabindex="-1">v3.0.4 — VM runtime regression correction <a class="header-anchor" href="#v3-0-4-—-vm-runtime-regression-correction" aria-label="Permalink to &quot;v3.0.4 — VM runtime regression correction&quot;">​</a></h2><p>Released 28 July 2026. This patch keeps the production <code>Compute/VirtualMachine</code> collector running when Azure returns repeated <code>MemoryGB</code> values in a Compute SKU payload.</p><h2 id="v3-0-3-—-production-runtime-collection" tabindex="-1">v3.0.3 — Production runtime collection <a class="header-anchor" href="#v3-0-3-—-production-runtime-collection" aria-label="Permalink to &quot;v3.0.3 — Production runtime collection&quot;">​</a></h2><p>Released 28 July 2026. This patch enables the hardened ARM-child, storage enrichment, and subscription security/policy collectors in normal extraction.</p><h2 id="v3-0-2-—-runtime-collector-hardening" tabindex="-1">v3.0.2 — Runtime collector hardening <a class="header-anchor" href="#v3-0-2-—-runtime-collector-hardening" aria-label="Permalink to &quot;v3.0.2 — Runtime collector hardening&quot;">​</a></h2><p>Released 28 July 2026. This patch stops queries to retired Application Insights endpoints and scopes storage service-property lookups to the resource-owning subscription.</p><h2 id="v3-0-1-—-tenant-scoped-authentication-and-wizard-correction" tabindex="-1">v3.0.1 — Tenant-scoped authentication and wizard correction <a class="header-anchor" href="#v3-0-1-—-tenant-scoped-authentication-and-wizard-correction" aria-label="Permalink to &quot;v3.0.1 — Tenant-scoped authentication and wizard correction&quot;">​</a></h2><p>Released 28 July 2026. This patch binds every Azure subscription context switch to the requested tenant, preventing unrelated cached-tenant authentication attempts during a tenant-scoped run. It also preserves the interactive wizard when PowerShell common parameters such as <code>-Debug</code> are supplied.</p><h2 id="v3-0-0-—-declarative-engine-rebuild" tabindex="-1">v3.0.0 — Declarative engine rebuild <a class="header-anchor" href="#v3-0-0-—-declarative-engine-rebuild" aria-label="Permalink to &quot;v3.0.0 — Declarative engine rebuild&quot;">​</a></h2><p>Released 26 July 2026, published to the PowerShell Gallery. Epic <strong>AB#5638</strong> — <strong>reopened</strong>; this release advanced it but did not complete it (see <a href="#the-engine-rebuild-is-in-progress-not-complete">above</a>).</p><p><strong>138 of 176 collectors are now declarative</strong>, up from 124. The audit had classified 20 cross-resource-join collectors as escape-hatch alongside those making live cmdlet calls. Re-examining all 48 showed the audit&#39;s <em>reasons</em> were right but its <em>inference</em> was not: <strong>a cross-resource join is not the same thing as a live cmdlet call.</strong> Each of those 20 filters the already-collected resource set a second time and correlates — data shaping over data the pipeline already holds. The only missing capability was somewhere to put statements that run <strong>once</strong>, before the row loop. Verified live: the run log reports <strong>138 declarative, 36 imperative</strong>.</p><p><strong>Definitions are now gated in CI</strong> by a validator that runs before the test suite, so a violation annotates the offending <code>.psd1</code> in the pull-request diff rather than surfacing as an empty worksheet at runtime. It includes a <strong>drift check</strong> — regenerating a definition from its source collector must reproduce it byte for byte. That check exists because a definition <strong>had already drifted for a release while its equivalence test stayed green</strong>; nothing in the repository could have caught it. The gate is proven to fail rather than assumed to: 13 tests each write one deliberately broken definition and assert the message names the fault.</p><p><strong>The honest limit, and the weakest part of the release:</strong> all 14 newly converted collectors agree with their imperative counterpart row for row, but the generated estate only makes <em>the join itself</em> change output for <strong>5</strong> of them. For the other 9, partners are present and both paths agree while both take the not-found branch. Each of the 9 is pinned by name, and a test asserts output changes when partners are removed — failing on a stale entry too, so the list can only shorten.</p><p><strong>Still imperative: 38</strong>, each with a specific reason — live REST or <code>Get-Az*</code> calls, conditional row shape or loop depth, a synthesised row set, or an unimplemented contract. No second escape hatch was invented; not having a definition remains it.</p><p><strong>Not done:</strong> reporting is still not cut over — the Excel job runs each collector&#39;s own reporting branch through its own duplicate discovery.</p><p>Live-verified: 5:37, 136 resources, 481 Excel rows, zero leftover background jobs, zero collector failures.</p><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#2110---2026-07-26" target="_blank" rel="noreferrer">CHANGELOG.md § 2.11.0</a>.</p><h2 id="previous-release-—-v2-10-0-—-the-declarative-collectors-actually-run" tabindex="-1">Previous Release — v2.10.0 — The Declarative Collectors Actually Run <a class="header-anchor" href="#previous-release-—-v2-10-0-—-the-declarative-collectors-actually-run" aria-label="Permalink to &quot;Previous Release — v2.10.0 — The Declarative Collectors Actually Run&quot;">​</a></h2><p>Released 26 July 2026, published to the PowerShell Gallery. Epic <strong>AB#5638</strong>.</p><p><strong>v2.9.0 converted 124 of 176 collectors to <code>.psd1</code> definitions — but nothing called the interpreter.</strong> The live pipeline still executed the imperative <code>.ps1</code> for every collector, so the conversion delivered nothing to a user. It now routes on the <code>HasDeclarativeDefinition</code> / <code>DefinitionPath</code> that <code>Get-ScoutCollector</code> already reported. Verified against a live tenant, the run log reports <strong>124 declarative, 50 imperative</strong>.</p><p>Proving this needed a different technique than the conversion did: <strong>a row comparison can never detect a routing regression</strong>, because both paths agree by construction. The proof is by impossibility — a fixture collector has a valid definition and a <code>.ps1</code> whose entire processing branch is a <code>throw</code>, and the run completes with its row present; with the kill switch on, the same fixture fails with that exact message. A full pass over an 845-resource estate produced <strong>1654 rows either way, zero deltas, and byte-identical ReportCache JSON</strong>.</p><p><strong>Kill switch:</strong> <code>AZURESCOUT_FORCE_IMPERATIVE_COLLECTORS=1</code> forces every collector down the imperative path — an environment variable, so it works on an already-installed build.</p><p><strong>The non-ARG collection half is inverted.</strong> <code>Get-ScoutApiResources</code>, <code>Get-ScoutVmQuotas</code>, <code>Get-ScoutVmSkuDetails</code> and <code>Get-ScoutCostInventory</code> — shipped in v2.7.0 and dead since — are now the real path, with the v1 ARM REST, quota/SKU and Cost Management implementations retired to shims and pinned by AST tests.</p><p><strong><code>Management/ManagementGroups</code> no longer fails the run</strong> — the only collector that failed on every live run. <strong>This is the first release with zero collector failures.</strong> A tenant still needs Management Group Reader at the root for that sheet to carry rows.</p><p><strong>Not done, stated rather than implied:</strong> reporting is not cut over. <code>Start-AZSCExcelJob</code> still runs each collector&#39;s <code>.ps1</code> reporting branch through its own duplicate discovery, so every definition&#39;s <code>Export</code> section is still exercised only by tests.</p><p>Live-verified: 6:37, 136 resources, 481 Excel rows, 43 worksheets, zero leftover background jobs.</p><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#2100---2026-07-26" target="_blank" rel="noreferrer">CHANGELOG.md § 2.10.0</a>.</p><h2 id="previous-release-—-v2-9-0-—-the-collectors-become-data-and-the-module-runs-strict" tabindex="-1">Previous Release — v2.9.0 — The Collectors Become Data, and the Module Runs Strict <a class="header-anchor" href="#previous-release-—-v2-9-0-—-the-collectors-become-data-and-the-module-runs-strict" aria-label="Permalink to &quot;Previous Release — v2.9.0 — The Collectors Become Data, and the Module Runs Strict&quot;">​</a></h2><p>Released 26 July 2026, published to the PowerShell Gallery. Second wave of the engine rebuild (Epic <strong>AB#5638</strong>).</p><p><strong>124 of 176 collectors are now <code>.psd1</code> definitions rather than PowerShell</strong>, up from 13. Every one is pinned by an equivalence test that runs the original imperative collector and the declarative definition over the same input, then compares processed rows key-by-key <em>and</em> the written <code>.xlsx</code> cell-by-cell, under both <code>-IncludeTags</code> states. Writing those tests found <strong>six interpreter defects</strong> that would otherwise have shipped — including a field whose source is an <code>if</code>/<code>else</code> <em>statement</em> being silently unreachable, and a dropped filter preamble that made one collector produce a <strong>silently empty sheet</strong>.</p><p><strong>All 174 collectors now pass under <code>Set-StrictMode -Version Latest</code></strong>, with a baseline that is empty because a run says so rather than aspirationally. Each conversion was proved real by running the collector twice with StrictMode off, before and after, and diffing emitted rows — 20 of 23 are byte-identical. A CI guard, AST-parsed rather than grepped, now fails the build if StrictMode is weakened anywhere in the module.</p><p><strong>A blind spot in error reporting closed.</strong> AB#402 detection compared <code>$Error.Count</code> before and after a phase, but <code>$Error</code> is a fixed-size ring buffer — once it saturates the count stops rising, the delta is permanently zero, and non-terminating errors stop being reported at all. Silently, and precisely in the long runs where degraded datasets matter most.</p><p><strong><code>ChartP6</code> root-caused:</strong> a worksheet that exists but holds no cells has a <code>$null</code> dimension, so ImportExcel&#39;s pivot source-range lookup threw, <code>Add-PivotTable</code> downgraded it to a warning, and the chart vanished with it. The guard tested existence, not emptiness.</p><p><strong><code>Management/ManagementGroups</code> was never a StrictMode fault</strong> — it fails parameter binding on <code>Get-AzManagementGroup -Expand -Recurse</code> with no <code>-GroupId</code>. That is the long-standing <em>&quot;missing mandatory parameters: GroupName&quot;</em> failure on every live run, finally explained.</p><p><strong>Known limits, stated rather than buried:</strong> the equivalence fixtures are <em>generated</em> by walking each definition&#39;s AST, not recorded from a tenant — they prove the two implementations agree on the same input, not that either is right about a real estate. The live pipeline still executes the imperative <code>.ps1</code> for every collector; converting is not the same as using. And of the 174 StrictMode passes, 146 emit zero rows because the capture covers only 32 resource types.</p><p>Live-verified: 4:52, 124 resources, 438 Excel rows, 42 worksheets, zero leftover background jobs.</p><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#290---2026-07-26" target="_blank" rel="noreferrer">CHANGELOG.md § 2.9.0</a>.</p><h2 id="previous-release-—-v2-8-0-—-collection-actually-happens-once" tabindex="-1">Previous Release — v2.8.0 — Collection Actually Happens Once <a class="header-anchor" href="#previous-release-—-v2-8-0-—-collection-actually-happens-once" aria-label="Permalink to &quot;Previous Release — v2.8.0 — Collection Actually Happens Once&quot;">​</a></h2><p>Released 26 July 2026, published to the PowerShell Gallery. Epic <strong>AB#5638</strong>, work item <strong>AB#5648</strong>.</p><p><strong>A default assessment collect now issues 4 Azure Resource Graph queries instead of 35.</strong></p><p>v2.7.0 shipped the single-pass collection functions, but nothing called them — outside tests the only reference to any of them was a comment — so the round-trip count was unchanged. They are now the real path. Both numbers were re-derived by counting invocations against a stub in place of <code>Search-AzGraph</code>, and both are pinned by hard count assertions in a test, because a query count with no test regresses silently within a release.</p><table tabindex="0"><thead><tr><th>Entry point</th><th>before</th><th>after</th></tr></thead><tbody><tr><td>Assessment-only collect (default)</td><td>35</td><td><strong>4</strong></td></tr><tr><td>Assessment collect, <code>-Source TypedQueries</code></td><td>35</td><td>35</td></tr><tr><td>Inventory extraction (default switches)</td><td>8</td><td>8</td></tr><tr><td>Combined inventory + assessment, end to end</td><td>9</td><td>9</td></tr></tbody></table><p>It is <strong>4 rather than 1</strong> for stated reasons: three raw tables plus <code>sqlDefenderPricing</code>, which reads <code>SecurityResources</code> and genuinely cannot be served from inventory. Inventory extraction stays at <strong>8</strong> because those are eight <em>distinct</em> ARG tables, not filters over one — merging them would drop datasets. What changed there is ownership rather than count: one paging implementation instead of two.</p><p>The legacy paging, batching and retry engine (<code>Invoke-AZTIInventoryLoop.ps1</code>) is <strong>deleted</strong>, and <code>Start-AZTIGraphExtraction</code> is reduced to a shim that builds no query text and issues no ARG call. Both facts are enforced by AST-based tests rather than text searches.</p><p><strong>A defect that would have shipped as a blank report section</strong>, invisible to all 2144 passing tests: the raw pass omits the <code>tags</code> column unless asked, while the collect contract aggregates its top-level <code>tags</code> key from <code>subscriptions[*].tags</code> — so the inverted path returned an empty <code>tags</code> array for every estate. Fixed, with a regression test.</p><p><strong>Trade-offs, stated and not yet measured:</strong> the raw pass carries the full <code>properties</code> bag where the typed queries carried narrow projections, so on a large estate the number of 1000-row pages can <em>rise</em> even as the query count falls; and <code>-Categories</code> no longer reduces what is fetched, only what is shaped. <code>-Source TypedQueries</code> remains fully supported as the escape hatch for a narrow single-category collect.</p><p><strong>Not claimed as done:</strong> the non-ARG half. <code>Get-ScoutApiResources</code>, <code>Get-ScoutVmQuotas</code>, <code>Get-ScoutVmSkuDetails</code> and <code>Get-ScoutCostInventory</code> remain dead code, and a live run still uses the v1 implementations for ARM REST, VM quota/SKU and Cost Management.</p><p>Live-verified: 5:11, 124 resources, 438 Excel rows, 42 worksheets, zero leftover background jobs.</p><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#280---2026-07-26" target="_blank" rel="noreferrer">CHANGELOG.md § 2.8.0</a>.</p><h2 id="previous-release-—-v2-7-0-—-reporting-leaves-modules-and-collectors-become-data" tabindex="-1">Previous Release — v2.7.0 — Reporting Leaves <code>Modules/</code>, and Collectors Become Data <a class="header-anchor" href="#previous-release-—-v2-7-0-—-reporting-leaves-modules-and-collectors-become-data" aria-label="Permalink to &quot;Previous Release — v2.7.0 — Reporting Leaves `Modules/`, and Collectors Become Data&quot;">​</a></h2><p>Released 26 July 2026, published to the PowerShell Gallery. Second phase of the engine rebuild (Epic <strong>AB#5638</strong>).</p><p><strong>Excel COM is gone.</strong> All 26 inventory report renderers moved out of <code>Modules/Private/Reporting/</code> into <code>src/report/renderers/</code>, each file renamed to match the function it defines, and <code>Build-AZTIExcelComObject.ps1</code> was deleted outright — chart styling now runs on EPPlus/ImportExcel only. COM is why <code>-Lite</code> defaulted to true, and why the module surfaced a raw <code>0x80040154 REGDB_E_CLASSNOTREG</code> on every machine and CI runner without Excel installed. Verified against a live tenant on a machine with no Excel: a 42-worksheet workbook, <code>SecurityCenter</code> carrying 489 rows.</p><p><strong>The first collector category is now data rather than code.</strong> All 13 Databases collectors ship as <code>.psd1</code> definitions interpreted at runtime. Each one is pinned by an equivalence test that runs the original imperative collector and the declarative definition over the same input, then compares the processed rows key-by-key <em>and</em> the written <code>.xlsx</code> cell-by-cell, under both <code>-IncludeTags</code> states. Writing that test caught two defects that would have silently changed shipped reports: tag columns were being appended rather than inserted, reordering the last three columns of every tagged worksheet, and <code>ResourceTypes</code> was applied as a membership test rather than a grouping.</p><p>An AST audit of all 176 collectors now ships alongside it: of the 163 that remain, <strong>115 are mechanically convertible</strong> and <strong>48 must stay hand-written</strong> — 29 make live cmdlet calls, 20 do cross-resource joins, 10 never filter <code>$Resources</code>, and 2 are unimplemented.</p><p><strong>A single-pass collection layer landed — as capability only.</strong> <code>src/collect/</code> gained five functions and a resource-type map covering 128 ARM types; one raw pass satisfies 34 of the 35 collect queries. But <strong>nothing in the product calls them yet</strong>, so a run still reaches Resource Graph exactly as often as it did in v2.6.0. Inverting the pipeline onto this layer is <strong>AB#5648</strong> and is not in this release.</p><p><strong>A defect that had shipped in every release:</strong> an unbound <code>[string[]]</code> parameter is <code>$null</code>, and <code>@($null).Count</code> is <strong>1</strong>, not 0 — so the subscription-resolution branch in <code>Invoke-Collect</code> never fired on the default path. The subscription list was never derived from <code>resourcecontainers</code>, and every later table degraded to a single un-batched tenant-wide call with none of the documented per-batch isolation. Same <code>@($null).Count</code> class as the empty-Excel-loop bug fixed in v2.6.0.</p><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#270---2026-07-26" target="_blank" rel="noreferrer">CHANGELOG.md § 2.7.0</a>.</p><h2 id="previous-release-—-v2-6-0-—-the-engine-stops-using-background-jobs" tabindex="-1">Previous Release — v2.6.0 — The Engine Stops Using Background Jobs <a class="header-anchor" href="#previous-release-—-v2-6-0-—-the-engine-stops-using-background-jobs" aria-label="Permalink to &quot;Previous Release — v2.6.0 — The Engine Stops Using Background Jobs&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery. First phase of the engine rebuild (Epic <strong>AB#5638</strong>).</p><p>The inventory processing phase used to create one <code>Start-Job</code> per category, and each of those created one <code>[PowerShell]::Create()</code> runspace <strong>per collector</strong>. Every defect of the v2.5.x wave lived in that coordination rather than in the collectors themselves: <code>Start-Job</code> is asynchronous, so a job still in <code>NotStarted</code> was excluded from the wait, harvested empty and then deleted — taking its whole category out of the report with no trace. The inner wait read <code>$Job.Runspace.IsCompleted</code>, but those handles have no <code>Runspace</code> property, so the loop never waited at all. Each job re-imported the module, which is why the v2.5.3 StrictMode opt-out needed <strong>17</strong> entry points. And category ordering came from <code>Get-Job</code>, so the same tenant could produce different reports on consecutive runs.</p><p>Collectors are pure functions of the resource set, so none of that concurrency was ever required. All 176 now run <strong>in-process, in a fixed order</strong>. Identical input produces an identical report cache — verified against a live tenant across two consecutive full runs: 32 collector sections compared, <strong>31 byte-identical</strong>, and the single difference checked against Resource Graph and confirmed as the estate genuinely changing between runs.</p><p>Resilience improved rather than regressed: each collector&#39;s failure is contained individually, so one bad collector no longer empties its category or aborts the batch. <code>Wait-AZSCJob</code> and the job machinery are <strong>deleted</strong>; the run orchestration starts no background jobs.</p><p><strong>Four defects that had shipped in every release surfaced the moment collectors ran in-process:</strong></p><ul><li>The <strong>Security Center worksheet had been empty in every release that had one</strong>. <code>Invoke-AZSCSecurityCenterJob</code> was called with <code>-SecurityCenter</code> against a parameter block that declared no such parameter — and PowerShell does not reject an unknown named argument to a simple function, it collects it into <code>$args</code> and carries on. <code>$null</code> crossed the job boundary as the security rows. It now carries real data.</li><li>Five collectors called <code>Write-AZSCLog -Color</code> / <code>-Level Verbose</code>, neither of which the function accepted, so each threw on its first log line and produced nothing.</li><li>Per-file <code>.CATEGORY</code> filtering had <strong>never matched a single file</strong> — the expression required a line break between the keyword and its value, and all 176 collectors write it on one line.</li><li>The Excel report loop invoked every collector whether or not it had data, because it counted rows with <code>@($SmaResources).count</code> and <strong><code>@($null).Count</code> is 1, not 0</strong>.</li></ul><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#260---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.6.0</a>.</p><h2 id="previous-release-—-v2-5-3-—-empty-is-not-null-and-runs-that-explain-themselves" tabindex="-1">Previous Release — v2.5.3 — Empty Is Not Null, and Runs That Explain Themselves <a class="header-anchor" href="#previous-release-—-v2-5-3-—-empty-is-not-null-and-runs-that-explain-themselves" aria-label="Permalink to &quot;Previous Release — v2.5.3 — Empty Is Not Null, and Runs That Explain Themselves&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery.</p><p>A full inventory run against a real tenant aborted with <code>The property &#39;ReservationRecomen&#39; cannot be found on this object</code>. It was not a null-reference fault. The module runs under <code>Set-StrictMode -Version Latest</code> — every <code>src/*.ps1</code> sets it at file scope and the <code>.psm1</code> dot-sources them — and under StrictMode, member enumeration over a collection reports a property as missing when the enumeration yields <strong>nothing at all</strong>. A <code>$null</code> value on every element is fine. An <strong>empty collection</strong> on every element is not: the empties flatten away and nothing remains. Azure returns <code>{ &quot;value&quot;: [] }</code> for a subscription with no reservation recommendations, so a perfectly healthy tenant crashed the run.</p><p>Because the fault is data-dependent, 1697 passing tests and three earlier live runs never saw it.</p><p>The same class was swept out of the two collectors that filter the mixed <code>$Resources</code> array in module scope — in <code>Get-AZSCVMQuotas</code> a bare <code>$_.subscriptionId</code> aborted the pipeline, so <strong>no</strong> subscription got quota data rather than merely the offending one. A diagram job wait that had never actually waited was fixed (the <code>.Runspace</code> no-op v2.5.2 corrected in only one of its two copies), and an unavailable Cost Management API no longer destroys the whole report.</p><p><strong>Every run now writes a diagnostic log into its own run folder</strong>, with no extra parameter: <code>scout-run.log</code> carries the run metadata, each phase with elapsed time and counts, warnings, and — on failure — the full error record including the failing script, line number and script stack trace. <code>scout-console.log</code> carries the transcript. It paid for itself during this release: two of the four defects above were found by reading the log rather than by re-running with <code>-Debug</code>.</p><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#253---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.5.3</a>.</p><h2 id="earlier-release-—-v2-5-2-—-determinism" tabindex="-1">Earlier Release — v2.5.2 — Determinism <a class="header-anchor" href="#earlier-release-—-v2-5-2-—-determinism" aria-label="Permalink to &quot;Earlier Release — v2.5.2 — Determinism&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery.</p><p>A whole report category could silently vanish from a run. <code>Start-Job</code> is asynchronous, so a job created moments earlier sits in <code>NotStarted</code> — a state the wait loop and the batch filter both ignored, so it was never waited on, then harvested and destroyed before it produced anything. <code>Compute.json</code> came back 5,158 bytes on one run and 470 on the next against an unchanged tenant.</p><p>Both now treat every non-terminal state as pending, a dropped category emits a warning naming it instead of failing silently, and a machine without Excel installed gets a plain one-line explanation rather than a raw COM <code>0x80040154</code> error on a run that otherwise succeeded.</p><p>Verified by <strong>three consecutive live runs producing byte-identical results</strong>: 227 Azure resources, 994 Excel rows, 40 Power BI files / 1013 rows, 166 Azure DevOps resources, 0 empty-category warnings, 0 raw COM errors.</p><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#252---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.5.2</a>.</p><h2 id="earlier-release-—-v2-5-1-—-live-run-hardening" tabindex="-1">Earlier Release — v2.5.1 — Live-Run Hardening <a class="header-anchor" href="#earlier-release-—-v2-5-1-—-live-run-hardening" aria-label="Permalink to &quot;Earlier Release — v2.5.1 — Live-Run Hardening&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery.</p><p>Seven defects stopped a full <code>Invoke-AzureScout</code> run from completing against a real tenant. Extraction and processing succeeded, then the reporting layer threw <em>after</em> every worksheet had already been built. Fixed: an uninitialised extraction variable, 41 <code>.IsPresent</code> reads on parameters that are not declared <code>[switch]</code>, Excel styling and tables applied over empty worksheets, VM property names the Compute collector never emitted, 29 unguarded worksheet dereferences, 10 pivot titles read before assignment, and a Markdown string-interpolation bug.</p><p><strong>Every one was found by running the product end to end against live Azure.</strong> The 1692-test suite passed the whole time, because nothing exercised the extraction, processing and reporting chain against real collector output. This release also carries the first live-tenant verification of the <code>-IncludeDevOps</code> collectors — 166 resources across 74 projects — which previously had only mocked tests.</p><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#251---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.5.1</a>.</p><h2 id="previous-release-—-v2-5-0-—-one-collection-pass" tabindex="-1">Previous Release — v2.5.0 — One Collection Pass <a class="header-anchor" href="#previous-release-—-v2-5-0-—-one-collection-pass" aria-label="Permalink to &quot;Previous Release — v2.5.0 — One Collection Pass&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery.</p><p>A combined inventory + assessment run now queries Azure <strong>once</strong> (AB#5543). The inventory pass already projects the full property bag for every resource, so the assessment shapes its scores from those rows rather than re-issuing its own Resource Graph pack over the same resource types. One query still goes to Azure in a combined run — the Defender for SQL pricing lookup, which reads a table the inventory does not collect. The assessment-only path is unchanged.</p><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#250---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.5.0</a>.</p><h2 id="previous-release-—-v2-4-0-—-one-command-and-a-guided-wizard" tabindex="-1">Previous Release — v2.4.0 — One Command, and a Guided Wizard <a class="header-anchor" href="#previous-release-—-v2-4-0-—-one-command-and-a-guided-wizard" aria-label="Permalink to &quot;Previous Release — v2.4.0 — One Command, and a Guided Wizard&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What shipped</th></tr></thead><tbody><tr><td>One entry point</td><td>Inventory and assessment are modes of a single <code>Invoke-AzureScout</code>, not two cmdlets. <code>-Assessment</code> selects the CAF/WAF assessment; <code>-CollectOnly</code> and <code>-FromCollect</code> moved across too. Assessment mode now honours the inventory sign-in parameters, which the standalone cmdlet never did (AB#5540)</td></tr><tr><td>Guided wizard</td><td>A bare <code>Invoke-AzureScout</code> in an interactive session signs you in, lets you pick the tenant, verifies your rights, then offers pre-selected checklists for run type, categories/assessments, formats, and report directory — and prints the equivalent one-liner. Never fires in CI; <code>-NoWizard</code> opts out (AB#5541)</td></tr><tr><td>Output formats</td><td><code>-OutputFormat</code> accepts several renderers in one run and spans both modes; a wrong-mode format now throws an error naming the switch you wanted</td></tr><tr><td>Assessment entry point</td><td>The former standalone assessment command is removed in v3.0.0; use <code>Invoke-AzureScout -Assessment</code></td></tr><tr><td>Documentation</td><td>Corrected pages claiming a PowerShell 5.1 floor the module never had, and collapsed the &quot;Inventory vs Assessment&quot; framing across the site</td></tr></tbody></table><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#240---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.4.0</a>.</p><div class="tip custom-block"><p class="custom-block-title">Resolved in v2.5.0</p><p>The duplicate collection pass described here was collapsed in v2.5.0 (AB#5543) — a combined run now collects from Azure once.</p></div><h2 id="v2-3-0-—-collection-hardening-external-platform-integrations" tabindex="-1">v2.3.0 — Collection Hardening &amp; External Platform Integrations <a class="header-anchor" href="#v2-3-0-—-collection-hardening-external-platform-integrations" aria-label="Permalink to &quot;v2.3.0 — Collection Hardening &amp; External Platform Integrations&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery. Closes the collection-hardening epic and the external-platform integrations.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What shipped</th></tr></thead><tbody><tr><td>Run isolation</td><td>Every invocation writes to its own run folder, so a rescan — or a scan of a second tenant — can no longer destroy the previous run&#39;s cache or report. <code>-RunName</code>, <code>-Force</code>, <code>Clear-AZSCCacheFolder -OlderThan &lt;days&gt;</code> (AB#331)</td></tr><tr><td>Azure DevOps inventory</td><td><code>-IncludeDevOps</code> adds projects, pipelines, service connections, repositories, and agent pools. The service-connection sheet cross-references each ARM connection against the subscriptions in scope (AB#327)</td></tr><tr><td>Unattended execution</td><td>Composite GitHub Action at the repository root (AB#328); the eight-step <a href="./../automation-guide/automation.html">Azure Automation Account</a> guide plus two runbook upload fixes (AB#343)</td></tr><tr><td>Reliability</td><td>Subscription context restored in a <code>finally</code> at all five <code>Set-AzContext</code> sites (AB#368); post-login management group access probe naming the role to assign (AB#351)</td></tr><tr><td>Documentation</td><td><a href="./../reference/category-reference.html">Category Reference</a> (AB#318/5417) and <a href="./../reference/validation-matrix.html">Validation Matrix</a> (AB#315)</td></tr></tbody></table><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#230---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.3.0</a>.</p><h2 id="v2-2-0-—-report-tiers-deeper-analytics-hardened-collectors" tabindex="-1">v2.2.0 — Report Tiers, Deeper Analytics, Hardened Collectors <a class="header-anchor" href="#v2-2-0-—-report-tiers-deeper-analytics-hardened-collectors" aria-label="Permalink to &quot;v2.2.0 — Report Tiers, Deeper Analytics, Hardened Collectors&quot;">​</a></h2><p>Four new report tiers, richer visuals on the existing ones, three new offline analysis functions, deeper collector coverage, and a round of platform hardening on top of v2.1.0.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What shipped</th></tr></thead><tbody><tr><td>Report tiers</td><td><code>Word</code> (<code>.docx</code> via OpenXML, AB#333), <code>EChartsDashboard</code> (offline ECharts HTML, AB#344), <code>Pdf</code> (dependency-free, AB#379/394/395), <code>JsonEvidence</code> (resources-only, AB#396) — all on <code>Export-Report</code> / <code>-OutputFormat</code></td></tr><tr><td>Reporting depth</td><td>Excel visual dashboard tabs with pivot charts (AB#322); richer React report — topology diagram, MG hierarchy, 14 KPI cards, Governance section, drill-downs, search/filter, badges, tooltips (AB#376–378, 380, 386, 387, 389–393); <code>report.pbit</code> generation (AB#5046)</td></tr><tr><td>New analysis</td><td><code>Get-ScoutInventoryDrift</code> (cross-run resource drift, AB#326), <code>Get-ScoutCostAnomaly</code> (cost outliers, AB#324), <code>Get-ScoutIacGap</code> (Bicep/IaC coverage gaps, AB#325) — all offline, never call Azure</td></tr><tr><td>Collect layer</td><td>IoT deep coverage — DPS + Digital Twins (AB#330); tag-value aggregation (AB#367); deeper Database/Analytics/IoT rule automation (AB#5068/5071/5075); per-subscription collector/pipeline resilience + live progress (AB#397–402, 405)</td></tr><tr><td>Config</td><td><code>Import-ScoutConfig</code> / <code>Export-ScoutConfig</code> (AB#373–375) — save/reload a benchmark + rule-selection + threshold-override config as JSON, with a safe fallback to the built-in default</td></tr><tr><td>Platform</td><td>CI pipeline (AB#317); a real, non-simulated <code>azure-inventory</code> workflow (AB#340); module auto-update check (AB#369); login auth banner (AB#349); five v1 inventory bug fixes (AB#335–340); draw.io merge/StrictMode repairs (AB#342); documented Entra Graph delegated scopes (AB#347/338)</td></tr></tbody></table><p>Full detail: <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CHANGELOG.md#220---2026-07-24" target="_blank" rel="noreferrer">CHANGELOG.md § 2.2.0</a>.</p><h2 id="v2-1-0-—-platform-hardening" tabindex="-1">v2.1.0 — Platform Hardening <a class="header-anchor" href="#v2-1-0-—-platform-hardening" aria-label="Permalink to &quot;v2.1.0 — Platform Hardening&quot;">​</a></h2><p>Released 23 July 2026. Native governance collector (AB#5041), unattended one-command pipeline (AB#5050), and the React report variant + cross-run drift tracking (AB#5053). See the <a href="#major-—-v2-1-0-—-platform-hardening-epic-ab-5023-carryover-—-released-2026-07-23">v2.1.0 section</a> below for the full breakdown.</p><h2 id="v2-0-0-—-caf-waf-assessment-platform" tabindex="-1">v2.0.0 — CAF/WAF Assessment Platform <a class="header-anchor" href="#v2-0-0-—-caf-waf-assessment-platform" aria-label="Permalink to &quot;v2.0.0 — CAF/WAF Assessment Platform&quot;">​</a></h2><p>Released 23 July 2026. Turns AzureScout from an inventory tool into a read-only CAF/WAF landing-zone assessment. Runtime-verified offline (Pester) and against a live Azure tenant.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What shipped</th></tr></thead><tbody><tr><td>Assessment engine</td><td>Declarative YAML rules (JSONPath + assert types), dual CAF/WAF scoring, prioritized gap list — <strong>139 rules across 8 CAF design areas + 5 WAF pillars</strong></td></tr><tr><td>Collect + ingest</td><td>Read-only ARG collect layer (<code>collect.json</code>); native governance collector (v2.1.0) / ARG query pack / Advisor ingest — AzGovViz retained as opt-in only</td></tr><tr><td>ALZ benchmark</td><td>Live tenant diffed against a canonical ALZ reference</td></tr><tr><td>Tiered reporting</td><td>Power BI, self-contained HTML, executive <strong>PowerPoint (OpenXML SDK — no Python)</strong>, Excel + JSON evidence</td></tr><tr><td>Per-domain analytics</td><td>Every discovery category runnable + tagged: <code>Invoke-AzureScout -Assessment &lt;Category&gt;</code></td></tr><tr><td>Entry point</td><td><code>Invoke-AzureScout -Assessment</code> (run one/some/all), read-only permission pre-flight</td></tr></tbody></table><blockquote><p><strong>Breaking:</strong> introduces the <code>findings.json</code> contract and demotes Excel-first output to an evidence tier. Assessment features require PowerShell 7.</p></blockquote><p>Deferred to v2.1.0: full per-category rule depth (AB#5061–5075). The native governance collector (AB#5041), the fully unattended pipeline (AB#5050), and the React report variant + cross-run drift tracking (AB#5053) shipped in v2.1.0; four new report tiers, deeper analysis functions, and collector hardening shipped in v2.2.0 above.</p><h2 id="previous-release-—-v1-0-0" tabindex="-1">Previous Release — v1.0.0 <a class="header-anchor" href="#previous-release-—-v1-0-0" aria-label="Permalink to &quot;Previous Release — v1.0.0&quot;">​</a></h2><p>Released February 2026.</p><table tabindex="0"><thead><tr><th>Area</th><th>What&#39;s included</th></tr></thead><tbody><tr><td>Excel Reports</td><td>171 worksheets (154 ARM + 17 Entra ID) covering all 15 Azure resource categories</td></tr><tr><td>Category Filtering</td><td><code>-Category</code> parameter to scope runs to specific resource types</td></tr><tr><td>AI / ML Coverage</td><td>27 modules: OpenAI, AI Foundry, Azure ML, Cognitive Services, Bot Services, Search</td></tr><tr><td>AVD Coverage</td><td>6 modules: Host Pools, App Groups, Workspaces, Session Hosts, Scaling Plans, Applications</td></tr><tr><td>Arc Coverage</td><td>Sites, SQL Servers, Data Controllers, SQL Managed Instances, Arc-enabled Kubernetes enhancements</td></tr><tr><td>VM &amp; Arc Enrichment</td><td>Backup status, Site Recovery, Update Manager, Advisor score, Monitor metrics, Cost estimates</td></tr><tr><td>Monitor Coverage</td><td>24 modules: Diagnostic settings, alert rules, DCRs, App Insights deep data, autoscale, workbooks</td></tr><tr><td>Markdown / AsciiDoc Export</td><td><code>-OutputFormat Markdown|AsciiDoc</code> generates portable reports alongside Excel/JSON</td></tr><tr><td>Permission Audit</td><td><code>Invoke-AZSCPermissionAudit</code> with ARM + Graph checks, color output, Markdown/AsciiDoc export</td></tr><tr><td>Subscription &amp; MG Completeness</td><td>Captures ALL subscriptions (including empty/disabled) and full MG hierarchy</td></tr><tr><td>Module Naming</td><td>Renamed from <em>AzureTenantInventory</em> to <em>AzureScout</em> (prefix: <code>AZSC</code>)</td></tr></tbody></table><h2 id="near-term-—-v1-1-0" tabindex="-1">Near-term — v1.1.0 <a class="header-anchor" href="#near-term-—-v1-1-0" aria-label="Permalink to &quot;Near-term — v1.1.0&quot;">​</a></h2><p>Focus: quality, reliability, and community onboarding.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Pester test suite</td><td>Full unit + integration tests for all public functions and key private functions</td><td>✅ Done — 1,648 tests across 56 files, run offline</td></tr><tr><td>PSGallery publish</td><td>Publish <code>AzureScout</code> module to PowerShell Gallery</td><td>✅ Done (v2.0.0)</td></tr><tr><td>GitHub Actions CI</td><td>Run Pester tests on PR + push; block merge on failure</td><td>✅ Done — <code>ci.yml</code> runs Pester + PSScriptAnalyzer on every push and PR</td></tr><tr><td>Category alias documentation</td><td>Comprehensive table of all accepted <code>-Category</code> aliases and their canonical names</td><td>✅ Done (v2.3.0, AB#318/AB#5417) — see <a href="./../reference/category-reference.html">Category Reference</a></td></tr><tr><td>Resource provider pre-flight</td><td>Warn before scan when required providers are not registered in a subscription</td><td>✅ Done — <code>-CheckResourceProviders</code></td></tr><tr><td>Throttling / retry improvements</td><td>Exponential backoff on 429 responses, honouring <code>Retry-After</code>, plus 5xx retry</td><td>✅ Done — <code>Invoke-AZSCGraphRequest</code> (<code>-MaxRetries</code>, default 5)</td></tr><tr><td><code>Invoke-AzureScout -WhatIf</code></td><td>Show which modules would run without actually executing</td><td>❌ Won&#39;t do (AB#321) — Azure Scout is read-only, so <code>-WhatIf</code> has no state change to preview</td></tr><tr><td>Non-destructive cache</td><td>Prevent <code>ReportCache</code> and <code>DiagramCache</code> from being overwritten on subsequent runs. Each invocation writes to a timestamped (or <code>-RunName</code> named) subfolder. Previous scan data is never lost unless <code>-Force</code> is specified. <code>Clear-AZSCCacheFolder -OlderThan &lt;days&gt;</code> for cleanup.</td><td>✅ Done (v2.3.0, AB#331)</td></tr><tr><td>Cross-subscription context restore</td><td>Restore the caller&#39;s subscription context after every per-subscription loop, including on error</td><td>✅ Done (v2.3.0, AB#368)</td></tr><tr><td>Management group access probe</td><td>Report management group visibility at login and name the role to assign when it is missing</td><td>✅ Done (v2.3.0, AB#351)</td></tr></tbody></table><h3 id="visual-dashboard-tabs-darkblue-overview-style-worksheets" tabindex="-1">Visual Dashboard Tabs (DarkBlue &quot;overview-style&quot; worksheets) <a class="header-anchor" href="#visual-dashboard-tabs-darkblue-overview-style-worksheets" aria-label="Permalink to &quot;Visual Dashboard Tabs (DarkBlue &quot;overview-style&quot; worksheets)&quot;">​</a></h3><p>Phase 10 added raw data tabs (Cost Management, Security Overview, Azure Update Manager, Azure Monitor) that collect data into flat tables. The next step is to add <strong>visual dashboard tabs</strong> — styled like the Overview sheet (DarkBlue tab color, EPPlus shapes, pivot charts) — that summarize and visualize the data from those raw tabs.</p><table tabindex="0"><thead><tr><th>Dashboard</th><th>Charts / Visualizations</th><th>Status</th></tr></thead><tbody><tr><td>Cost Dashboard</td><td>Cost by Resource Type (bar), Cost by Subscription (pie), Cost by Region (column), Cost by SKU (bar)</td><td>:blue_circle: Planned</td></tr><tr><td>Security Dashboard</td><td>Assessments by Severity (pie), Findings by Subscription (bar), Defender Plans (column), Active Alerts by Severity (bar)</td><td>:blue_circle: Planned</td></tr><tr><td>Update Manager Dashboard</td><td>Machines by Platform (pie), Machines by OS Type (pie), Machines by Region (column), Machines by Power State (bar), Machines by Subscription (bar)</td><td>:blue_circle: Planned</td></tr><tr><td>Monitor Dashboard</td><td>Alert Rules by Subscription (bar), Action Groups by Subscription (pie), DCRs by Subscription (column), App Insights by Subscription (bar)</td><td>:blue_circle: Planned</td></tr></tbody></table><p>Each dashboard tab will:</p><ul><li>Use DarkBlue tab color (matching Overview, Subscriptions, Advisor)</li><li>Be pinned after the Overview sheet group via <code>MoveAfter</code> in the ordering function</li><li>Contain EPPlus pivot tables + charts generated by <code>Build-AZSCDashboardTabs</code></li><li>Only appear when the corresponding raw data tab has data (no empty dashboards)</li></ul><h2 id="medium-term-—-v1-2-0" tabindex="-1">Medium-term — v1.2.0 <a class="header-anchor" href="#medium-term-—-v1-2-0" aria-label="Permalink to &quot;Medium-term — v1.2.0&quot;">​</a></h2><p>Focus: depth, breadth, and multi-tenant scenarios.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Multi-tenant scanning (Lighthouse)</td><td><code>-TenantID</code> accepts multiple tenant IDs. Authenticates to each tenant sequentially, runs the full extraction → processing → reporting pipeline per tenant. Supports combined workbook (with Tenant column) or separate per-tenant workbooks via <code>-MergeOutput</code> switch. Auth failure on one tenant does not block others. The run-isolation prerequisite shipped in v2.3.0 (AB#331).</td><td>💡 Idea (AB#323)</td></tr><tr><td>Word document export (#22)</td><td>Shipped as <code>-OutputFormat Word</code> in assessment mode: <code>Export-Word</code> generates a self-contained <code>.docx</code> via OpenXML, no Python.</td><td>✅ Done (v2.2.0, AB#333)</td></tr><tr><td>PDF report export (#23)</td><td>Shipped as <code>-OutputFormat Pdf</code> in assessment mode: <code>Export-Pdf</code> is a hand-rolled, dependency-free renderer (cover, executive summary, per-area findings table, gaps, manual review).</td><td>✅ Done (v2.2.0, AB#379/394/395)</td></tr><tr><td>Cost anomaly detection</td><td>Shipped as the offline <code>Get-ScoutCostAnomaly</code> function (v2.2.0) — flags statistical outliers (spike/z-score/IQR) in an already-collected cost dataset; never calls Azure.</td><td>✅ Done (v2.2.0, AB#324)</td></tr><tr><td>Bicep / IaC gap detection</td><td>Shipped as the offline <code>Get-ScoutIacGap</code> function (v2.2.0) — compares discovered resources against a folder of Bicep/ARM-JSON templates and flags unmanaged resources; never calls Azure.</td><td>✅ Done (v2.2.0, AB#325)</td></tr><tr><td>Resource drift reporting</td><td>Shipped as the offline <code>Get-ScoutInventoryDrift</code> function (v2.2.0) — compares the current <code>collect.json</code> against the previous run&#39;s snapshot and reports Added/Removed/Changed resources.</td><td>✅ Done (v2.2.0, AB#326)</td></tr><tr><td>Azure DevOps integration</td><td>Shipped as <code>-IncludeDevOps</code> (v2.3.0) — inventories projects, pipelines, service connections, repositories, and agent pools across one or more organizations, adding five worksheets. Authentication reuses the current Azure sign-in; <code>-DevOpsPat</code> covers a separate identity. The ADO Service Connections sheet cross-references each ARM connection against the subscriptions in scope.</td><td>✅ Done (v2.3.0, AB#327)</td></tr><tr><td>GitHub Actions module</td><td>Shipped as a composite <code>action.yml</code> at the repository root (v2.3.0) — <code>uses: Hybrid-Solutions-Cloud/azure-scout@v2</code> installs the module, authenticates, collects, and uploads reports as an artifact.</td><td>✅ Done (v2.3.0, AB#328)</td></tr><tr><td>Azure Automation Account</td><td>Shipped as first-class unattended execution (v2.3.0) — the eight-step setup guide now exists, plus fixes for the blob-upload collision on a second scheduled run and the diagnostic log that never uploaded.</td><td>✅ Done (v2.3.0, AB#343)</td></tr><tr><td>Fabric / Power BI export (#17)</td><td><code>-OutputFormat PowerBI</code> generates a flat normalized CSV bundle (<code>PowerBI/</code> folder) with <code>_metadata.csv</code>, <code>Subscriptions.csv</code>, per-module <code>Resources_*.csv</code> and <code>Entra_*.csv</code> files, and a <code>_relationships.json</code> star-schema manifest for Power BI Desktop / Microsoft Fabric</td><td>✅ Done</td></tr><tr><td>IoT deep coverage</td><td>Shipped in the assessment Collect layer (v2.2.0) — <code>Invoke-Collect</code> gains Device Provisioning Service and Azure Digital Twins queries; new <code>caf.iot</code> rules score them.</td><td>✅ Done (v2.2.0, AB#330)</td></tr></tbody></table><h2 id="major-—-v2-0-0-—-caf-waf-assessment-platform-epic-ab-5023-—-delivered" tabindex="-1">Major — v2.0.0 — CAF/WAF Assessment Platform (Epic AB#5023) — Delivered <a class="header-anchor" href="#major-—-v2-0-0-—-caf-waf-assessment-platform-epic-ab-5023-—-delivered" aria-label="Permalink to &quot;Major — v2.0.0 — CAF/WAF Assessment Platform (Epic AB#5023) — Delivered&quot;">​</a></h2><p>Turned inventory into a <strong>scored CAF/WAF landing-zone assessment</strong>. Collection stays as-is; a three-layer, JSON-on-disk architecture (<code>collect.json</code> → <code>findings.json</code> → deliverables) adds assessment and rebuilds reporting. Read-only throughout. <strong>Shipped in v2.0.0 (2026-07-23).</strong></p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Assessment engine</td><td>Declarative YAML rules (JSONPath + assert types), dual CAF/WAF scoring, prioritized gap list</td><td>✅ Done (AB#5027, AB#5034)</td></tr><tr><td>CAF/WAF rule content</td><td>8 CAF design areas + 5 WAF pillars — 139 rules across 23 version-controlled files</td><td>✅ Done (AB#5031, AB#5057)</td></tr><tr><td>Ingest layer</td><td>Fold an ARG query pack and Advisor into one <code>collect.json</code>; governance now ingested natively by default (see v2.1.0 below) — Azure Governance Visualizer remains available as an opt-in ingestor</td><td>✅ Done (AB#5037)</td></tr><tr><td>ALZ benchmark diff</td><td>Compare the live tenant against a canonical ALZ reference (MG archetypes, required policies)</td><td>✅ Done — engine + native governance collection, no upstream AzGovViz dependency (AB#5041, v2.1.0)</td></tr><tr><td>Tiered reporting</td><td>Power BI (primary), self-contained HTML, executive PPTX (OpenXML SDK); Excel/JSON retained as evidence</td><td>✅ Done (AB#5044)</td></tr><tr><td>Module registry + entry point</td><td><code>-Assessment</code> run one/some/all; read-only permission pre-flight</td><td>✅ Done (AB#5024); unattended one-command pipeline ✅ Done (AB#5050, v2.1.0)</td></tr><tr><td>React report + drift tracking</td><td>Richer React report variant and cross-run score-drift tracking</td><td>✅ Done (AB#5053, v2.1.0)</td></tr></tbody></table><h2 id="major-—-v2-1-0-—-platform-hardening-epic-ab-5023-carryover-—-released-2026-07-23" tabindex="-1">Major — v2.1.0 — Platform Hardening (Epic AB#5023 carryover) — Released 2026-07-23 <a class="header-anchor" href="#major-—-v2-1-0-—-platform-hardening-epic-ab-5023-carryover-—-released-2026-07-23" aria-label="Permalink to &quot;Major — v2.1.0 — Platform Hardening (Epic AB#5023 carryover) — Released 2026-07-23&quot;">​</a></h2><p>Three more Epic AB#5023 capabilities shipped ahead of the full per-domain analytics epic below. Tagged and released as <code>v2.1.0</code> — see <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/RELEASES.md" target="_blank" rel="noreferrer"><code>RELEASES.md</code></a> for the build ledger.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Native governance collector</td><td><code>Import-Governance</code> replaces the AzGovViz hard dependency as the <strong>default</strong> governance collector — populates <code>collect.json</code>&#39;s <code>governance</code> object natively from Azure Resource Graph and ambient-token ARM REST, needing only Reader at the management-group root. No cloned repo, no <code>AzAPICall</code> install prompt, fully unattended, StrictMode-safe. Live-verified against the HCS tenant. <code>AzGovViz</code> remains available as an opt-in <code>Ingest</code> value; nothing depends on it by default anymore.</td><td>✅ Done (AB#5041)</td></tr><tr><td>Unattended pipeline</td><td><code>Invoke-ScoutPipeline</code> runs collect → assess → report headless into one dated run folder — non-interactive throughout, runs the read-only permission pre-flight first, and degrades to <code>PartialSuccess</code> (rather than losing output) if an exporter fails. Writes <code>pipeline-summary.json</code>/<code>.md</code>.</td><td>✅ Done (AB#5050)</td></tr><tr><td>React report + cross-run drift</td><td><code>-OutputFormat React</code> renders a single self-contained <code>report-react.html</code> (client-side filter/sort/search, summary dashboard, Drift tab). <code>Get-ScoutDrift</code> computes cross-run New / Resolved / Regressed / Unchanged findings plus a weighted score delta, tracked in an append-only <code>.scout-history/findings-history.json</code>.</td><td>✅ Done (AB#5053)</td></tr></tbody></table><p>Not included in v2.1.0: full per-category rule depth (AB#5061–5075) — tracked below. Four new report tiers, richer report visuals, and three new offline analysis functions shipped in v2.2.0 next.</p><h2 id="major-—-v2-2-0-—-report-tiers-deeper-analytics-hardened-collectors" tabindex="-1">Major — v2.2.0 — Report Tiers, Deeper Analytics, Hardened Collectors <a class="header-anchor" href="#major-—-v2-2-0-—-report-tiers-deeper-analytics-hardened-collectors" aria-label="Permalink to &quot;Major — v2.2.0 — Report Tiers, Deeper Analytics, Hardened Collectors&quot;">​</a></h2><p>Delivered on <code>main</code> — not yet tagged/published, see <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/RELEASES.md" target="_blank" rel="noreferrer"><code>RELEASES.md</code></a> for cut status.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Report tiers — Word/ECharts/PDF/JSON evidence</td><td><code>Export-Word</code> (<code>.docx</code> via OpenXML), <code>Export-EChartsDashboard</code> (offline ECharts HTML, no CDN), <code>Export-Pdf</code> (hand-rolled, dependency-free), <code>Export-JsonEvidence</code> (resources-only JSON, no assessment metadata/scores). All wired into <code>Export-Report</code>, <code>Invoke-AzureScout -Assessment</code>, and <code>Invoke-ScoutPipeline</code>.</td><td>✅ Done (AB#333, AB#344, AB#396, AB#379/394/395)</td></tr><tr><td>Excel visual dashboard tabs</td><td>Native ImportExcel PivotTable/PivotChart dashboard sheets in the assessment Excel evidence tier: Findings-by-Severity (pie), Score-by-Area (column), Pass-Fail-Manual (stacked column), Resource-Counts (bar) — omitted when a sheet&#39;s data is empty.</td><td>✅ Done (AB#322)</td></tr><tr><td>Richer React report + <code>report.pbit</code></td><td>The self-contained <code>report-react.html</code> gains a vis.js VNet topology diagram, an MG-hierarchy diagram, 14 KPI cards, an Azure Firewall drill-down, a Governance section (budgets/locks/tag chips), a policy-enforcement badge, per-section search/filter, clickable rows with a side panel, and scope tooltips. The Power BI tier also generates a <code>report.pbit</code> bound to the star-schema CSVs.</td><td>✅ Done (AB#376–378, 380, 386, 387, 389–393, AB#5046)</td></tr><tr><td>Cross-run resource drift</td><td><code>Get-ScoutInventoryDrift</code> — offline, compares the current <code>collect.json</code> against the previous run and reports Added/Removed/Changed resources, complementing the existing findings-level <code>Get-ScoutDrift</code> (v2.1.0).</td><td>✅ Done (AB#326)</td></tr><tr><td>Cost anomaly detection</td><td><code>Get-ScoutCostAnomaly</code> — offline, flags statistical outliers (month-over-month spike, z-score, IQR) in an already-collected cost dataset.</td><td>✅ Done (AB#324)</td></tr><tr><td>Bicep / IaC gap detection</td><td><code>Get-ScoutIacGap</code> — offline, compares discovered resources against a folder of Bicep/ARM-JSON templates (best-effort text/JSON parsing) and flags resources not represented in any template.</td><td>✅ Done (AB#325)</td></tr><tr><td>IoT deep coverage</td><td><code>Invoke-Collect</code> gains Device Provisioning Service and Azure Digital Twins queries; new <code>caf.iot</code> rules score them.</td><td>✅ Done (AB#330)</td></tr><tr><td>Tag aggregation</td><td><code>Invoke-Collect</code> aggregates tag values to their unique set per key across subscriptions instead of last-write-wins.</td><td>✅ Done (AB#367)</td></tr><tr><td>Database/Analytics/IoT rule depth</td><td>New <code>sqlDefenderPricing</code>/<code>purviewAccounts</code> collect queries plus <code>iotHubs.disableLocalAuth</code>; CAF-DB-04, CAF-ANL-02, and new CAF-IOT-06 flip from <code>Manual</code> to automated.</td><td>✅ Done (AB#5068, AB#5071, AB#5075)</td></tr><tr><td>Collector/pipeline resilience + progress</td><td>Per-subscription try/catch/continue in <code>Invoke-Collect</code>; a management-group role-requirement hint on RP/authorization errors; an empty-data guard; a pipeline <code>HadErrors</code> summary flag; live <code>Write-ScoutProgress</code> output during collection.</td><td>✅ Done (AB#397–402, AB#405)</td></tr><tr><td>Assessment config load/save</td><td><code>Import-ScoutConfig</code> / <code>Export-ScoutConfig</code> — load/save an alternative benchmark, rule-selection patterns, and per-rule threshold overrides as JSON; never throws on a bad file (falls back to the built-in default with a warning).</td><td>✅ Done (AB#373–375)</td></tr><tr><td>Platform hardening</td><td>CI pipeline (<code>ci.yml</code>); a real, non-simulated <code>azure-inventory</code> workflow; module auto-update check on import; UPN/subscription auth banner; five v1 inventory bug fixes; draw.io merge/StrictMode repairs; documented Entra Graph delegated scopes.</td><td>✅ Done (AB#317, AB#340, AB#369, AB#349, AB#335–340, AB#342, AB#347/338)</td></tr></tbody></table><p>Not yet included: full per-category rule depth (AB#5061–5075) — tracked below under Epic AB#5056.</p><h2 id="major-—-v2-1-0-—-per-domain-caf-waf-analytics-epic-ab-5056" tabindex="-1">Major — v2.1.0 — Per-Domain CAF/WAF Analytics (Epic AB#5056) <a class="header-anchor" href="#major-—-v2-1-0-—-per-domain-caf-waf-analytics-epic-ab-5056" aria-label="Permalink to &quot;Major — v2.1.0 — Per-Domain CAF/WAF Analytics (Epic AB#5056)&quot;">​</a></h2><p>Focus: extend CAF/WAF analytics to <strong>every</strong> Scout category, not just the landing-zone roll-up. Each of the 15 discovery categories becomes an <strong>independently runnable, categorized and tagged assessment</strong> — so you can run and score <em>just</em> Governance, <em>just</em> Monitoring, <em>just</em> Update Manager, etc.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Assessment taxonomy &amp; tagging</td><td>Manifest gains <code>Category</code> / <code>Frameworks</code> / <code>Tags</code>; <code>-Assessment &lt;Category&gt;</code> runs scoped discovery + scoped scoring; sub-bundles (Governance/Policy/UpdateManager under Management, Monitoring under Monitor)</td><td>:blue_circle: Planned (AB#5057)</td></tr><tr><td>Per-category coverage</td><td>CAF/WAF rule coverage authored for each category — Management, Monitor, Networking, Identity, Security, Compute, Storage, Databases, Containers, Web, Analytics, AI, Integration, Hybrid, IoT</td><td>:blue_circle: Planned (AB#5061–AB#5075)</td></tr><tr><td>Registry document</td><td>A table of every possible assessment: category, sub-bundles, CAF areas, WAF pillars, tags</td><td>:blue_circle: Planned (AB#5057)</td></tr></tbody></table><p>See <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/RELEASES.md" target="_blank" rel="noreferrer"><code>RELEASES.md</code></a> for the build/release ledger.</p><h2 id="far-future-—-web-version-of-azure-scout-epic-ab-5093" tabindex="-1">Far-future — Web version of Azure Scout (Epic AB#5093) <a class="header-anchor" href="#far-future-—-web-version-of-azure-scout-epic-ab-5093" aria-label="Permalink to &quot;Far-future — Web version of Azure Scout (Epic AB#5093)&quot;">​</a></h2><blockquote><p>A <strong>web-UI version with the same capabilities as the PowerShell version</strong> — same engine, browser instead of terminal. <strong>Far-future, not scheduled.</strong> Only the web-only plumbing (server, runspace, progress polling, launchers) is unique to it. The actual product features are <strong>buildable in the PowerShell version now</strong> (Epic AB#5094) and the web version inherits them.</p></blockquote><blockquote><p><strong>Status: under evaluation — NOT committed.</strong> This is a possible future direction, not planned work, and it would be a <strong>departure from the current &quot;no portals&quot; stance</strong> in the <a href="#long-term-vision">Long-term Vision</a> below. Captured here so the direction is tracked and can be decided deliberately rather than drifting into the backlog.</p></blockquote><p>A <strong>served web-application</strong> as a <strong>second delivery surface</strong> for the same engine — not a different product. It would run a local HTTP listener with a browser UI (background-runspace collection with live progress, interactive vis.js topology, in-browser PDF export, config upload/download). <strong>The web portal must reach FEATURE PARITY with the PowerShell version</strong> — every product feature is available through both surfaces; neither has a feature the other lacks. Only the <em>delivery plumbing</em> below is web-specific. It is weeks of net-new engineering (web server + JS front-end + IPC layer).</p><p><strong>Web delivery surface — plumbing only (Epic AB#5093, exploratory):</strong></p><table tabindex="0"><thead><tr><th>Area</th><th>Web-surface plumbing (no PowerShell equivalent)</th><th>Status</th></tr></thead><tbody><tr><td>Server core</td><td>HTTP listener + background runspace, file-based progress IPC (client polls), named stages %, concurrent-collection guard, cached-inventory serving, runspace disposal, double-poll guard</td><td>💡 Exploratory (AB#381–385, 403, 404)</td></tr><tr><td>Launchers</td><td><code>start.cmd</code> / <code>start.sh</code> to launch the server</td><td>💡 Exploratory (AB#388)</td></tr></tbody></table><h3 id="feature-parity-—-shared-across-both-surfaces-epic-ab-5094" tabindex="-1">Feature parity — shared across both surfaces (Epic AB#5094) <a class="header-anchor" href="#feature-parity-—-shared-across-both-surfaces-epic-ab-5094" aria-label="Permalink to &quot;Feature parity — shared across both surfaces (Epic AB#5094)&quot;">​</a></h3><p>The product <strong>features</strong> below are <strong>not web-only or PowerShell-only — they belong to both surfaces</strong>. They live in the core product and are surfaced through the PowerShell module (CLI + static/React reports) <em>and</em> the web portal. Same capability, per-surface delivery:</p><ul><li><strong>Report visuals</strong> (in the React/HTML report today, and the web portal later): vis.js VNet topology + click-to-details + reset/fit controls, MG-hierarchy diagram, per-section search/filter, clickable rows + side panel, 14 KPI cards, Azure Firewall drill-down, Governance section (budgets/locks/tag chips), policy-enforcement badge, scope tooltips, resources-only JSON evidence export (AB#376–378, 380, 386, 387, 389–393, 396). <em>Several partially exist in the React report already — extend them.</em></li><li><strong>WAF config load/save + report PDF export</strong> (PowerShell via parameters/file output; web via browser upload/download + in-browser render) (AB#373–375, 379, 394, 395).</li><li><strong>Collector / pipeline resilience</strong> (shared engine): per-subscription try/catch/continue, MG role-requirement hint, false RP-registration-error swallow, per-group firewall-parse-error logging, empty-data guard, pipeline-<code>HadErrors</code> warning capture (AB#397–402).</li><li><strong>Live-progress UX</strong> — same feature, per-surface delivery: AzureScout&#39;s native TUI in the CLI, browser progress in the web portal (AB#405).</li></ul><h2 id="long-term-vision" tabindex="-1">Long-term Vision <a class="header-anchor" href="#long-term-vision" aria-label="Permalink to &quot;Long-term Vision&quot;">​</a></h2><p>AzureScout aims to be the definitive open-source Azure visibility tool for:</p><ul><li><strong>Architects</strong> — understand the full shape of a tenant before designing changes</li><li><strong>Security teams</strong> — identify misconfigured, unmonitored, or over-privileged resources</li><li><strong>FinOps practitioners</strong> — surface cost waste, reservation opportunities, and untagged resources</li><li><strong>Managed service providers</strong> — generate client-ready reports across multiple tenants</li></ul><p>The tool will remain <strong>open-source, PowerShell-native, and Excel-friendly</strong> — no agents, no portals, no licensing fees.</p><h2 id="completed-phases" tabindex="-1">Completed Phases <a class="header-anchor" href="#completed-phases" aria-label="Permalink to &quot;Completed Phases&quot;">​</a></h2><p>All implementation phases from the original migration plan are complete. See the <a href="./changelog.html">Changelog</a> for the full history.</p><table tabindex="0"><thead><tr><th>Phase</th><th>Summary</th></tr></thead><tbody><tr><td>Phase 1-9</td><td>Core engine, module loading, Excel generation, JSON output, Draw.io diagrams, auth methods, connection handling, permission pre-flight</td></tr><tr><td>Phase 10</td><td>Specialized Excel tabs: Cost Management, Security Overview, Azure Update Manager, Azure Monitor</td></tr><tr><td>Phase 11</td><td>All-subscriptions + full MG hierarchy enumeration</td></tr><tr><td>Phase 12</td><td>ARM-only default scope, permission documentation, README overhaul</td></tr><tr><td>Phase 13</td><td>15 new Azure Monitor/Insights modules</td></tr><tr><td>Phase 14</td><td>15 new AI/ML modules</td></tr><tr><td>Phase 15</td><td>6 AVD modules + AVD on Azure Local/Arc detection</td></tr><tr><td>Phase 16</td><td>Arc site configs, Arc SQL Server, Arc Data Services enhancements</td></tr><tr><td>Phase 17</td><td>VM + Arc deep enrichment (metrics, backup, DR, cost, advisor)</td></tr><tr><td>Phase 18</td><td>Category folder alignment + <code>.CATEGORY</code> metadata parsing</td></tr><tr><td>Phase 19</td><td>Richer progress indicators, clear permission error messages</td></tr><tr><td>Phase 20</td><td><code>Invoke-AZSCPermissionAudit</code> + <code>Test-AZSCPermissions</code> refactor</td></tr><tr><td>Phase 21</td><td>Markdown + AsciiDoc export, <code>Export-AZSCMarkdownReport</code>, <code>Export-AZSCAsciiDocReport</code></td></tr></tbody></table><h2 id="suggest-a-feature" tabindex="-1">Suggest a Feature <a class="header-anchor" href="#suggest-a-feature" aria-label="Permalink to &quot;Suggest a Feature&quot;">​</a></h2><p>Open an issue at <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/issues" target="_blank" rel="noreferrer">github.com/Hybrid-Solutions-Cloud/azure-scout/issues</a> with the label <code>enhancement</code>.</p><p>Pull requests are welcome — see <a href="./contributing.html">Contributing</a> for guidelines.</p><h2 id="fork-attribution" tabindex="-1">Fork Attribution <a class="header-anchor" href="#fork-attribution" aria-label="Permalink to &quot;Fork Attribution&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Fork Attribution</p><p><strong>AzureScout is a fork of <a href="https://github.com/microsoft/ARI" target="_blank" rel="noreferrer">Azure Resource Inventory (ARI)</a></strong> by Microsoft, originally created by <a href="https://github.com/Claudio-Merola" target="_blank" rel="noreferrer">Claudio Merola</a> and <a href="https://github.com/RenatoGregio" target="_blank" rel="noreferrer">Renato Gregio</a>. The ARI project provided the entire foundation that AzureScout builds upon — its ARM inventory module set, the draw.io diagram engine, Excel reporting, and more. AzureScout is now at 240 collector definitions across all 18 Azure service categories — see <a href="./../reference/arm-modules.html">ARM Modules</a> and <a href="./../reference/entra-modules.html">Entra ID Modules</a>. We are deeply grateful for their work.</p><p>See <a href="./credits.html">Credits &amp; Attribution</a> for full details, or <a href="./ari-differences.html">Differences from ARI</a> for what has changed.</p></div>',230)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
